-- S10: 16 candidatas, 128 vectores, sin juicio ni promoción.
BEGIN;
DO $s10$
DECLARE p jsonb; q jsonb; e jsonb; cd text; lid int; n int:=0; b_leg jsonb; b_bridge jsonb; b_pub jsonb; b_dep jsonb; b_judge jsonb; b_cand int;
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_leg FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY legacy_id,nucleo_codigo,version_nucleo) INTO b_bridge FROM lf_ops.lf_nucleo_cobertura_legada t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_pub FROM lf_ops.nucleo_regla_versiones t WHERE estado='PUBLICADA';
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_judge FROM lf_ops.nucleo_juicios t;
 SELECT count(*) INTO b_cand FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND ((SELECT count(distinct legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>180 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='PUBLICADA')<>215 OR b_cand NOT IN (12,37)) THEN RAISE EXCEPTION 'S10_BASELINE_DRIFT'; END IF;
